import { muzzleBallistics, type BallisticSpec } from './fps-ballistics';
import type { ThreatClass } from './armor-inserts';
export type ShopCategory = 'weapon' | 'skin' | 'rig' | 'plate' | 'vehicleSkin' | 'consumable' | 'loadout' | 'vision';
export type SupplyType = 'food' | 'medical' | 'field-utility';
export type AttachmentSlot = 'optic' | 'magazine' | 'handling' | 'muzzle' | 'rail';
/**
 * Rarity, lowest first. The first three are the ladder every platform climbs;
 * the top three mark how heavily kitted a variant is, so a weapon carrying a
 * can, a sight and a rail device out-ranks one that only has a better barrel.
 */
export const ITEM_TIERS = ['Issued', 'Field', 'Elite', 'Ultra', 'Legendary', 'Mythic'] as const;
export type ItemTier = typeof ITEM_TIERS[number];
/** Where a tier sits in `ITEM_TIERS`: 0 for Issued up to 5 for Mythic. */
export const tierRank = (tier: ItemTier) => ITEM_TIERS.indexOf(tier);
/**
 * The order weapons are shelved in: what unlocks first, then the lower rarity
 * at the same level, then credits before tokens and the cheaper first.
 */
export function byUnlock(a: ShopItem, b: ShopItem) {
  return (a.requiredLevel ?? 1) - (b.requiredLevel ?? 1) || tierRank(a.tier) - tierRank(b.tier)
    || Number(a.currency === 'tokens') - Number(b.currency === 'tokens') || a.price - b.price || a.name.localeCompare(b.name);
}
/**
 * Internal hardware a variant is built from: a barrel, a carrier, a drum. It
 * takes no attachment slot and is not sold on its own, but a variant's figures
 * are the sum of its parts rather than numbers written next to its name, so the
 * shop can say which part is responsible for which gain.
 *
 * Numeric fields are added to the platform's own figure, except `mobility`,
 * which multiplies, and `ballistics`, which replaces.
 */
export interface InternalPart {
  id: string; name: string; description: string;
  /** Optional chambering change supplied by a complete variant. */
  caliberMm?: number;
  damage?: number; capacity?: number; interval?: number; reload?: number; recoil?: number; recoilRecovery?: number;
  mobility?: number; ballistics?: BallisticSpec; traits?: readonly WeaponTrait[];
  /** A trigger group that changes how the weapon fires, which replaces. */
  fireMode?: WeaponSpec['fireMode'];
  /** What the weapon is fed from, which replaces: a drum-fed gun taking box magazines. */
  feed?: WeaponFeed;
}
/** Fixed hardware included in a weapon variant, never sold or swapped separately. */
export interface FittedPart {
  slot: AttachmentSlot; name: string; description: string;
  stats?: Partial<Omit<WeaponSpec, 'traits'>>;
  /** `velocity` scales muzzle velocity, as a can or a longer slide does. */
  modifiers?: { capacity?: number; reload?: number; recoil?: number; recoilRecovery?: number; aimFov?: number; mobility?: number; velocity?: number };
  traits?: readonly WeaponTrait[];
  /** What the part does besides its figures: a can, a laser, a sight housing (weapon-accessories). */
  accessories?: WeaponAccessories;
}
export interface ShopItem {
  bipod?: BipodKind;
  /** Arcade carry mass: whole weapon/armor item, or one supply. */
  weightKg?: number;
  requiresMount?: boolean;
  /** In-world flavour, displayed separately from the factual gameplay description. */
  flavorText?: string;
  /**
   * `enemy`: carried by opposing forces and only ever taken from them. Never
   * sold, never issued, never in a supply crate, and it lasts the expedition.
   */
  source?: 'enemy';
  /** Weapons only: which of the platform model's fixed configurations this variant is. */
  config?: string;
  /**
   * Weapons only: a sidegrade within its tier rather than a rung of the
   * ladder, trading one strength for another (drill-range speed for reach, a
   * cycle for a laser). It is not ranked against its own tier. Lower tiers
   * below its level must lose to it everywhere; higher ones must beat it at
   * drill range, where everyone fights, but not at what it specialises in
   * (`mustOutrank`, `outrankFailures` in armory-balance), or they would inherit
   * every sidegrade's strength at once. The breakpoint analysis measures it
   * against the platform's issued baseline.
   */
  specialist?: true;
  id: string; name: string; category: ShopCategory; description: string; price: number; currency: 'credits' | 'tokens';
  tier: ItemTier; requiredLevel?: number; family?: number; slot?: AttachmentSlot;
  /** Scalar overrides. Traits live in `traits` so the two never resolve twice. */
  stats?: Partial<Omit<WeaponSpec, 'traits'>>; traits?: readonly WeaponTrait[];
  /** Weapons only: the internal hardware their figures are computed from. */
  build?: readonly InternalPart[];
  /** Weapons only: hardware already installed, which fixes those slots. */
  fitted?: readonly FittedPart[];
  modifiers?: { capacity?: number; reload?: number; recoil?: number; recoilRecovery?: number; aimFov?: number; mobility?: number };
  palette?: string[]; accent?: string; protection?: number; absorption?: number; mobility?: number; carry?: number;
  /** Inserts only: the heaviest rounds it takes its full share of (armor-inserts); rifle rounds when unset. */
  stops?: ThreatClass;
  /** Inserts only: it smells, and gives the wearer away (armor-inserts `SCENT`). */
  scent?: true;
  /** Inserts only: the chance a round glances off it altogether. */
  deflect?: number;
  /** Consumables share the quick slot, but the exchange presents local food separately from field utilities. */
  supplyType?: SupplyType;
  /** Medical supplies only: a dressing is wound on, a kit is opened and worked through. Sets the belt slot it fills. */
  medical?: 'dressing' | 'kit';
  /** Consumables only: what one use restores. Reserve is per equipped weapon. */
  effect?: { health?: number; armor?: number; reserve?: number };
}
